import { readFileSync } from "node:fs";
import path from "node:path";

import type { ScoreSummary } from "@/lib/score/score";

const FIXTURES = path.join(import.meta.dirname, "../../e2e/fixtures");

/** Bytes of a file in e2e/fixtures (generated by scripts/make-fixtures.mjs). */
export function fixtureBytes(name: string): Uint8Array {
  return new Uint8Array(readFileSync(path.join(FIXTURES, name)));
}

